type HistogramOperation_Function int32

const (
	HistogramOperation_FUNCTION_UNSET HistogramOperation_Function = 0
	// Returns HistogramPointSeries for explicit histograms.
	// Returns ExponentialHistogramPointSeries for exponential histograms.
	//
	// For cumulative histograms, the server computes the per-step delta first,
	// handles resets, and only then emits bucketed results.
	HistogramOperation_BUCKETS HistogramOperation_Function = 1
	// Returns NumberPointSeries, one output series per requested quantile,
	// with synthetic label "quantile".
	//
	// For cumulative histograms, the server computes the per-step delta first.
	HistogramOperation_QUANTILE HistogramOperation_Function = 2
	// Returns NumberPointSeries.
	HistogramOperation_AVG   HistogramOperation_Function = 3
	HistogramOperation_COUNT HistogramOperation_Function = 4
	HistogramOperation_SUM   HistogramOperation_Function = 5
	// For windowed cumulative histograms, min/max cannot be derived by delta.
	// Server should only return these when it can compute them correctly.
	HistogramOperation_MIN HistogramOperation_Function = 6
	HistogramOperation_MAX HistogramOperation_Function = 7
)

